[CmdletBinding()]param([string]$HandoffRoot='C:\Scripts\AntigravityProjects\companion-handoff',[switch]$Apply)
$ErrorActionPreference='Stop';if(!(Test-Path $HandoffRoot -PathType Container)){Write-Host 'Companion Handoff not installed; integration skipped.';exit 0};$Config=Join-Path $HandoffRoot 'handoff.config.json';if(!(Test-Path $Config)){throw "handoff.config.json missing: $Config"};$Obj=Get-Content $Config -Raw|ConvertFrom-Json;$Members=@('.agy/ACTION_PACKET_RECEIPT.json','.agy/PROGRESS_POLICY.json','.agy/PROGRESS_STATE.json','.agy/NEXT_ACTION.json','.agy/CANDIDATE_MANIFEST.json','.agy/CANDIDATE_MANIFEST_STATUS.json','.agy/inbox/ACTIVE_ACTION_PACKET/ACTION_PACKET.json','.agy/inbox/ACTIVE_ACTION_PACKET/AGENT_TASK.md','.agy/inbox/ACTIVE_ACTION_PACKET/OWNER_SUMMARY_RU.md');if(-not($Obj.PSObject.Properties.Name-contains'additional_authority_paths')){$Obj|Add-Member -NotePropertyName additional_authority_paths -NotePropertyValue @()};$Obj.additional_authority_paths=@($Obj.additional_authority_paths+$Members|Sort-Object -Unique);if(-not($Obj.PSObject.Properties.Name-contains'ecosystem_version')){$Obj|Add-Member -NotePropertyName ecosystem_version -NotePropertyValue '1.2.8'}else{$Obj.ecosystem_version='1.2.8'};if($Apply){Copy-Item $Config ($Config+'.pre-1.2.8.bak') -Force;[IO.File]::WriteAllText($Config,($Obj|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false));Write-Host 'Agentic Context Handoff integration 1.2.8 applied.'}else{$Obj|ConvertTo-Json -Depth 30}
